example:
service jobs from cron {
    cors { origins: ["https://app.example.com"] }   // ✗ a schedule has no browser callers
    on schedule("0 0 * * *") () -> Effect[Result[(), String]] { … }
}

service api from http {
    cors { origins: ["https://app.example.com"] }   // ✓
    on GET("/items") () -> Effect[HttpResult[String]] by v: Visitor { … }
}
